arguments.command:
set -o pipefail
REPO='github/copilot-sdk'; OWNER='github'; NAME='copilot-sdk'; PR=2173; TASK=2168; EXPECTED_BASE='edburns/1917-java-embed-rust-cli-runtime-dd-3039924-agentic-run-02'; VALIDATED_HEAD='fb56fbe426e51eaecd3198d8b3cddc4013ce4058'
PR_JSON=$(gh api "/repos/$REPO/pulls/$PR")
STATE=$(printf '%s' "$PR_JSON" | jq -r '.state'); DRAFT=$(printf '%s' "$PR_JSON" | jq -r '.draft'); BASE=$(printf '%s' "$PR_JSON" | jq -r '.base.ref'); HEAD=$(printf '%s' "$PR_JSON" | jq -r '.head.sha'); CHANGED=$(printf '%s' "$PR_JSON" | jq -r '.changed_files'); BASE_SHA=$(printf '%s' "$PR_JSON" | jq -r '.base.sha')
[ "$STATE" = 'open' ] && [ "$DRAFT" = 'true' ] && [ "$BASE" = "$EXPECTED_BASE" ] && [ "$HEAD" = "$VALIDATED_HEAD" ] || { echo "ERROR state=$STATE draft=$DRAFT base=$BASE head=$HEAD"; exit 1; }
LINKED=$(gh api graphql -f query='query($owner:String!,$name:String!,$number:Int!){repository(owner:$owner,name:$name){pullRequest(number:$number){closingIssuesReferences(first:100){nodes{number}}}}}' -F owner="$OWNER" -F name="$NAME" -F number="$PR" --jq ".data.repository.pullRequest.closingIssuesReferences.nodes[] | select(.number == $TASK) | .number")
[ "$LINKED" = "$TASK" ] || { echo 'ERROR closing link'; exit 2; }
TIMELINE=$(gh api "/repos/$REPO/issues/$PR/timeline?per_page=100" -H 'Accept: application/vnd.github+json')
START=$(printf '%s' "$TIMELINE" | jq -r '[.[]|select(.event=="copilot_work_started")|.created_at]|max//empty'); FINISH=$(printf '%s' "$TIMELINE" | jq -r '[.[]|select(.event=="copilot_work_finished")|.created_at]|max//empty')
[ -n "$START" ] && [ -n "$FINISH" ] && { [[ "$FINISH" > "$START" ]] || [[ "$FINISH" == "$START" ]]; } || { echo "ERROR work cycle start=$START finish=$FINISH"; exit 3; }
FILES=$(gh api "/repos/$REPO/pulls/$PR/files?per_page=100" --paginate --jq '.[].filename'); FILE_COUNT=$(printf '%s\n' "$FILES" | sed '/^$/d' | wc -l); BASE_TREE=$(gh api "/repos/$REPO/git/commits/$BASE_SHA" --jq '.tree.sha'); HEAD_TREE=$(gh api "/repos/$REPO/git/commits/$HEAD" --jq '.tree.sha')
[ "$CHANGED" -gt 0 ] && [ "$FILE_COUNT" -gt 0 ] && [ "$BASE_TREE" != "$HEAD_TREE" ] || { echo 'ERROR empty effective diff'; exit 4; }
CHECKS=$(gh api "/repos/$REPO/commits/$HEAD/check-runs?per_page=100" --paginate | jq -s '[.[].check_runs[]]')
PENDING=$(printf '%s' "$CHECKS" | jq '[.[]|select(.status!="completed")]|length'); FAILING=$(printf '%s' "$CHECKS" | jq '[.[]|select(.status=="completed")|select(.conclusion!="success" and .conclusion!="skipped" and .conclusion!="neutral")]|length'); JAVA17=$(printf '%s' "$CHECKS" | jq '[.[]|select(.name=="java / Java SDK Tests (JDK 17)" and .conclusion=="success")]|length'); JAVA25=$(printf '%s' "$CHECKS" | jq '[.[]|select(.name=="java / Java SDK Tests (JDK 25)" and .conclusion=="success")]|length')
[ "$PENDING" -eq 0 ] && [ "$FAILING" -eq 0 ] && [ "$JAVA17" -gt 0 ] && [ "$JAVA25" -gt 0 ] || { echo "ERROR checks pending=$PENDING failing=$FAILING java17=$JAVA17 java25=$JAVA25"; exit 5; }
REVIEW=$(gh api graphql -f query='query($owner:String!,$name:String!,$number:Int!){repository(owner:$owner,name:$name){pullRequest(number:$number){reviewDecision reviewThreads(first:100){nodes{isResolved comments(last:1){nodes{author{login} body url}}}pageInfo{hasNextPage endCursor}}}}}' -F owner="$OWNER" -F name="$NAME" -F number="$PR")
UNRESOLVED=$(printf '%s' "$REVIEW" | jq '[.data.repository.pullRequest.reviewThreads.nodes[]|select(.isResolved==false)]|length'); DECISION=$(printf '%s' "$REVIEW" | jq -r '.data.repository.pullRequest.reviewDecision//empty'); HAS_MORE=$(printf '%s' "$REVIEW" | jq -r '.data.repository.pullRequest.reviewThreads.pageInfo.hasNextPage')
[ "$UNRESOLVED" -eq 0 ] && [ "$DECISION" != 'CHANGES_REQUESTED' ] && [ "$HAS_MORE" = 'false' ] || { echo "ERROR reviews unresolved=$UNRESOLVED decision=$DECISION has_more=$HAS_MORE"; exit 6; }
CURRENT_HEAD=$(gh pr view "$PR" -R "$REPO" --json headRefOid --jq '.headRefOid'); [ "$CURRENT_HEAD" = "$VALIDATED_HEAD" ] || { echo "ERROR HEAD changed to $CURRENT_HEAD"; exit 7; }
printf 'FINAL_GATE_PASS pr=%s head=%s state=%s draft=%s base=%s linked_task=%s start=%s finish=%s changed_files=%s file_count=%s pending=%s failing=%s java17=%s java25=%s unresolved=%s review_decision=%s\n' "$PR" "$HEAD" "$STATE" "$DRAFT" "$BASE" "$LINKED" "$START" "$FINISH" "$CHANGED" "$FILE_COUNT" "$PENDING" "$FAILING" "$JAVA17" "$JAVA25" "$UNRESOLVED" "${DECISION:-none}"

